import glob
import os
import tarfile
from typing import Iterable, List


_WORKSPACE = "/workspace"
_ARCHIVE_DIR = os.path.join(_WORKSPACE, "archives")


def _candidate_patterns(log_pattern: str) -> Iterable[str]:
    """Return legacy-compatible patterns to try for a caller supplied pattern."""
    pattern = str(log_pattern)
    yield pattern

    if not os.path.isabs(pattern):
        # Legacy callers commonly pass paths relative to /workspace, e.g.
        # "logs/service_app".
        yield os.path.join(_WORKSPACE, pattern)

        # Older callers also pass names relative to /workspace/logs, e.g.
        # "service_app" or "service_*".
        if not pattern.startswith("logs" + os.sep) and pattern != "logs":
            yield os.path.join(_WORKSPACE, "logs", pattern)


def _expand_log_pattern(log_pattern: str) -> List[str]:
    matches: List[str] = []
    seen = set()

    for pattern in _candidate_patterns(log_pattern):
        expanded = glob.glob(pattern)
        if not expanded and os.path.exists(pattern):
            expanded = [pattern]

        for path in expanded:
            abs_path = os.path.abspath(path)
            if abs_path not in seen and os.path.exists(abs_path):
                seen.add(abs_path)
                matches.append(abs_path)

    return matches


def archive_logs(log_pattern: str, archive_name: str) -> bool:
    """Create a tar.gz archive for a legacy log path or shell glob pattern."""
    try:
        name = os.path.basename(str(archive_name))
        if not name:
            return False
        if not name.endswith(".tar.gz"):
            name += ".tar.gz"

        os.makedirs(_ARCHIVE_DIR, exist_ok=True)
        out_path = os.path.join(_ARCHIVE_DIR, name)

        matches = _expand_log_pattern(log_pattern)
        if not matches:
            return False

        with tarfile.open(out_path, "w:gz") as tar:
            for path in matches:
                # Store entries relative to /workspace when possible, matching
                # the legacy tar command's useful layout without relying on a shell.
                try:
                    arcname = os.path.relpath(path, _WORKSPACE)
                    if arcname.startswith(".." + os.sep) or arcname == "..":
                        arcname = os.path.basename(path)
                except ValueError:
                    arcname = os.path.basename(path)
                tar.add(path, arcname=arcname)

        return os.path.exists(out_path)
    except Exception:
        return False
